/* SOURCE: src/core-layout.css */
/* 宇宙 · SillyTavern 1.14.0 布局约束
 * 保留官方消息 Flex、抽屉几何、滚动与输入事件。
 */

#chat .mes[is_user="false"]:not([is_system="true"]) {
    width: min(96%, 1080px);
    margin-inline: auto 1.5%;
}

#chat .mes[is_user="true"]:not([is_system="true"]) {
    width: min(68%, 720px);
    margin-inline: 2% auto;
}

#chat .mes:not([is_system="true"]) > .mes_block {
    flex: 1 1 auto;
    width: auto;
    min-width: 0;
    margin-inline: 0;
}

#chat .mes:not([is_system="true"]) > .mesAvatarWrapper {
    flex: 0 0 auto;
}

/* H001：角色头像保持右上，不改节点与事件。 */
#chat .mes[is_user="false"] > .mesAvatarWrapper {
    order: 2;
    align-self: flex-start;
    margin-inline: 18px 0;
}

/* H002：用户头像保持左下。 */
#chat .mes[is_user="true"] > .mesAvatarWrapper {
    order: 0;
    align-self: flex-end;
    margin-inline: 0 18px;
}

/* SOURCE: src/visual.css */
/* 宇宙 · 黑白月相编辑主题 */

@font-face {
    font-family: "Source Han Serif SC";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/sourcehanserifsc/sourcehanserifsc.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

@font-face {
    font-family: "Cormorant SC";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/cormorant-sc/CormorantSC-Regular.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

:root {
    --universe-void: #101013;
    --universe-surface: #15161a;
    --universe-surface-2: #1b1c21;
    --universe-surface-3: #22242a;
    --universe-light: #e9ecf2;
    --universe-silver: #bfc3cc;
    --universe-muted: #92959f;
    --universe-rule: #52555c;
    --universe-rule-soft: rgba(191, 195, 204, 0.22);
    --universe-rule-mid: rgba(191, 195, 204, 0.42);
    --universe-glow: 0 0 18px rgba(233, 236, 242, 0.08);
    --universe-shadow: 0 18px 44px rgba(0, 0, 0, 0.44);
    --universe-radius-sm: 2px;
    --universe-radius-md: 4px;
    --universe-radius-lg: 4px;
    --universe-font-body: "Source Han Serif SC", "Noto Serif CJK SC", "Songti SC", SimSun, serif;
    --universe-font-label: "Cormorant SC", "Source Han Serif SC", Georgia, serif;
    --universe-font-ui: "Microsoft YaHei UI", "Noto Sans CJK SC", system-ui, sans-serif;
    --universe-font-mono: "Cascadia Mono", "Noto Sans Mono", Consolas, monospace;
    --mainFontFamily: var(--universe-font-body);
    --universe-main-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/4f14875904d6bc3318b0af6e1c4e52a6379941c3/assets/%E5%AE%87%E5%AE%99/cosmos-editorial-v2.png");
    --universe-left-spine: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/4f14875904d6bc3318b0af6e1c4e52a6379941c3/assets/%E5%AE%87%E5%AE%99/lunar-spine-transparent-v3.png");
    --universe-text: var(--universe-light);
    --universe-white: var(--universe-light);
    --universe-ink: var(--universe-void);
    --universe-dim: var(--universe-rule);
    --universe-panel-solid: var(--universe-surface);
    --universe-field: var(--universe-surface-2);
    --universe-border: var(--universe-rule-mid);
    --universe-border-soft: var(--universe-rule-soft);
    --universe-display-font: var(--universe-font-label);
    --universe-panel-map:
        radial-gradient(circle at 9% 14%, rgba(233, 236, 242, .16) 0 1px, transparent 1.7px),
        radial-gradient(circle at 79% 21%, rgba(191, 195, 204, .12) 0 1px, transparent 1.8px),
        radial-gradient(circle at 64% 82%, rgba(146, 149, 159, .12) 0 1px, transparent 1.7px),
        linear-gradient(112deg, rgba(16, 16, 19, .98) 0 38%, rgba(16, 16, 19, .84) 68%, rgba(16, 16, 19, .72)),
        var(--universe-main-image);
}

body {
    color: var(--universe-light);
    background-color: var(--universe-void);
    background-image: var(--universe-main-image);
    background-position: right bottom;
    background-repeat: no-repeat;
    background-size: cover;
    background-attachment: fixed;
    background-blend-mode: normal;
    font-family: var(--universe-font-body);
    text-shadow: none;
}

#sheld,
#form_sheld {
    background-color: transparent;
}

:is(#chat, #top-bar, #send_form, .drawer-content, .popup, .options-content, .menu) {
    scrollbar-color: var(--universe-rule) transparent;
}

:is(#chat, #top-bar, #send_form, .drawer-content, .popup, .options-content, .menu) :focus-visible {
    outline: 1px solid var(--universe-light);
    outline-offset: 3px;
}

::selection {
    color: var(--universe-void);
    background: var(--universe-silver);
}

/* SOURCE: src/windows/chat.css */
/* ================================================================
   W01 页面背景与主聊天
   ================================================================ */
#sheld {
    border-inline: 1px solid rgba(191, 195, 204, .26);
    box-shadow: 0 0 54px rgba(0, 0, 0, .58);
}

#chat {
    color: var(--universe-light);
    border-inline: 1px solid rgba(191, 195, 204, .24);
    background-color: rgba(16, 16, 19, .42);
    background-image:
        linear-gradient(90deg, rgba(16, 16, 19, .84) 0%, rgba(16, 16, 19, .72) 48%, rgba(16, 16, 19, .3) 100%),
        var(--universe-main-image);
    background-position: center, right bottom;
    background-repeat: no-repeat, no-repeat;
    background-size: 100% 100%, cover;
    background-attachment: scroll, fixed;
    background-blend-mode: normal, normal;
    text-shadow: none;
}

#chat .mes:not([is_system="true"]) {
    box-sizing: border-box;
    margin-block: 0 22px;
    padding: 18px clamp(14px, 2vw, 28px) 22px;
    color: var(--universe-light);
    border: 0;
    border-top: 1px solid rgba(191, 195, 204, .24);
    border-bottom: 1px solid rgba(191, 195, 204, .24);
    border-radius: 0;
    background: linear-gradient(90deg, rgba(16, 16, 19, .84), rgba(16, 16, 19, .42) 72%, rgba(16, 16, 19, .18));
    box-shadow: none;
}

#chat .mes[is_user="true"] {
    border-left: 1px solid rgba(233, 236, 242, .58);
    background: linear-gradient(102deg, rgba(27, 28, 33, .94), rgba(16, 16, 19, .68) 78%, rgba(16, 16, 19, .46));
}

#chat .mes[is_user="false"]:not([is_system="true"]) {
    padding-block: 22px 28px;
    border: 1px solid rgba(191, 195, 204, .28);
    border-right-color: rgba(233, 236, 242, .62);
    background-color: rgba(16, 16, 19, .78);
    background-image:
        linear-gradient(90deg, rgba(16, 16, 19, .94), rgba(16, 16, 19, .72) 70%, rgba(16, 16, 19, .34)),
        var(--universe-left-spine);
    background-position: center, calc(100% - 20px) top;
    background-repeat: no-repeat, repeat-y;
    background-size: 100% 100%, clamp(168px, 11vw, 190px) auto;
    background-blend-mode: normal, normal;
}

#chat .mes:not([is_system="true"]) > .mes_block {
    color: var(--universe-light);
    overflow-x: hidden;
}

#chat .mes[is_user="false"]:not([is_system="true"]) > .mes_block {
    padding-inline-end: clamp(104px, 9.2vw, 146px);
}

#chat .mesAvatarWrapper .avatar {
    border: 1px solid var(--universe-silver);
    border-radius: 50%;
    background-color: var(--universe-void);
    box-shadow:
        0 0 0 3px var(--universe-void),
        0 0 0 4px var(--universe-rule),
        0 0 22px rgba(233, 236, 242, .18);
}

#chat .mesAvatarWrapper .avatar img {
    border-radius: 50%;
}

#chat .ch_name {
    min-height: 0;
    padding: 3px 0 7px;
    color: var(--universe-light);
    border: 0;
    border-bottom: 1px solid rgba(82, 85, 92, .62);
    font-family: var(--universe-font-label);
}

#chat .mes[is_user="false"]:not([is_system="true"]) .ch_name {
    margin-bottom: 12px;
    padding-block: 5px 10px;
    border-top: 1px solid rgba(191, 195, 204, .2);
    border-bottom-color: rgba(233, 236, 242, .46);
}

#chat .name_text {
    color: var(--universe-light);
    font-family: var(--universe-font-label);
    font-weight: 400;
    letter-spacing: 0.12em;
}

#chat .mes[is_user="true"] .name_text::after {
    content: "  /  USER";
    color: var(--universe-muted);
    font-size: 0.82em;
    letter-spacing: 0.16em;
}

#chat .mes[is_user="false"] .name_text::after {
    content: "  /  CHARACTER";
    color: var(--universe-muted);
    font-size: 0.82em;
    letter-spacing: 0.16em;
}

#chat .timestamp,
#chat .mesIDDisplay,
#chat .tokenCounterDisplay {
    color: var(--universe-muted);
    font-family: var(--universe-font-label);
    font-size: 0.78em;
    letter-spacing: 0.08em;
}

#chat :is(.mes_text, .mes_reasoning) {
    color: var(--universe-light);
    font-family: var(--universe-font-body);
    font-size: clamp(15.5px, 1vw, 17.5px);
    font-weight: 400;
    line-height: 1.94;
    letter-spacing: 0.025em;
    overflow-wrap: anywhere;
}

#chat .mes[is_user="true"] :is(.mes_text, .mes_reasoning) {
    padding: 12px 14px 12px;
    border-left: 1px solid rgba(191, 195, 204, .62);
}

#chat .mes[is_user="false"] :is(.mes_text, .mes_reasoning) {
    padding: 12px 14px 18px;
    border-right: 0;
}

#chat .mes_reasoning_header {
    color: var(--universe-silver);
    border: 1px solid var(--universe-rule);
    border-radius: var(--universe-radius-sm);
    background-color: var(--universe-surface-2);
    box-shadow: none;
    text-shadow: none;
}

#chat .mes_reasoning_header:hover,
#chat .mes_reasoning_details[open] .mes_reasoning_header {
    color: var(--universe-light);
    border-color: var(--universe-silver);
    background-color: var(--universe-surface-3);
}

#chat .mes_reasoning_arrow {
    color: var(--universe-silver);
    opacity: 1;
    filter: none;
}

#chat :is(.mes_text, .mes_reasoning) blockquote {
    margin: 0.9em 0;
    padding: 10px 16px;
    color: var(--universe-silver);
    border-left: 2px solid var(--universe-silver);
    background-color: rgba(82, 85, 92, 0.18);
}

#chat :is(.mes_text, .mes_reasoning) hr {
    height: 1px;
    margin: 1.4em auto;
    border: 0;
    background: linear-gradient(90deg, transparent, var(--universe-silver), transparent);
}

#chat :is(.mes_text, .mes_reasoning) pre {
    color: var(--universe-light);
    border: 1px solid var(--universe-rule);
    border-radius: var(--universe-radius-sm);
    background-color: var(--universe-surface);
    box-shadow: inset 2px 0 0 var(--universe-silver);
}

#chat :is(.mes_text, .mes_reasoning) :is(pre, code) {
    font-family: var(--universe-font-mono);
}

#chat :is(.mes_buttons, .mes_edit_buttons, .mes_reasoning_actions, .mes_button, .extraMesButtons > div) {
    color: var(--universe-muted);
    opacity: 0.88;
    filter: none;
    text-shadow: none;
}

#chat :is(.mes_button, .extraMesButtons > div, .mes_edit_buttons .menu_button, .mes_reasoning_actions .edit_button):hover {
    color: var(--universe-light);
    opacity: 1;
    filter: none;
}

#chat :is(.reasoning_edit_textarea, .edit_textarea) {
    color: var(--universe-light);
    border: 1px solid var(--universe-silver);
    background-color: var(--universe-surface);
    box-shadow: inset 2px 0 0 var(--universe-silver);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#chat .mes[is_system="true"] {
    width: min(88%, 780px);
    margin: 8px auto;
    color: var(--universe-silver);
    border: 1px dashed var(--universe-rule);
    border-radius: var(--universe-radius-md);
    background-color: rgba(21, 22, 26, 0.96);
}

/* SOURCE: src/windows/topbar.css */
/* ================================================================
   W02 顶栏九入口：真实 drawer-icon 上的九种天体标记，无发光
   ================================================================ */
#top-bar,
#top-settings-holder {
    color: var(--universe-silver);
    border-bottom: 1px solid rgba(191, 195, 204, .4);
    border-radius: 0;
    background:
        radial-gradient(circle at 8% 35%, rgba(233, 236, 242, .14) 0 1px, transparent 1.7px),
        radial-gradient(circle at 38% 72%, rgba(191, 195, 204, .12) 0 1px, transparent 1.7px),
        radial-gradient(circle at 82% 22%, rgba(146, 149, 159, .12) 0 1px, transparent 1.7px),
        linear-gradient(90deg, rgba(16, 16, 19, .99), rgba(27, 28, 33, .96) 50%, rgba(16, 16, 19, .99));
    box-shadow: none;
    text-shadow: none !important;
}

#top-settings-holder > :is(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > .drawer-toggle {
    position: relative;
    color: var(--universe-muted);
    border: 0;
    border-bottom: 1px solid transparent;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
    text-shadow: none !important;
    filter: none !important;
    transition: color 150ms ease, border-color 150ms ease, transform 150ms ease;
}

/* Font Awesome 图标在这一层，旧版只改 drawer-toggle 因而没有真正命中。 */
#top-settings-holder > :is(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > .drawer-toggle > .drawer-icon {
    position: relative;
    color: var(--universe-muted);
    opacity: .78;
    text-shadow: none !important;
    filter: none !important;
    transition: color 150ms ease, opacity 150ms ease, transform 150ms ease;
}

/* 每个入口使用不同天体标记；原功能图标仍在，远程素材失效也不影响识别。 */
#top-settings-holder .drawer-icon::after {
    position: absolute;
    right: -.22em;
    bottom: -.12em;
    color: var(--universe-light);
    font: 400 .34em/1 var(--universe-font-label);
    opacity: .92;
    pointer-events: none;
    text-shadow: none !important;
}

#ai-config-button .drawer-icon::after { content: "✦"; }
#sys-settings-button .drawer-icon::after { content: "◑"; }
#advanced-formatting-button .drawer-icon::after { content: "☾"; }
#WI-SP-button .drawer-icon::after { content: "✧"; }
#user-settings-button .drawer-icon::after { content: "⊙"; }
#backgrounds-button .drawer-icon::after { content: "◒"; }
#extensions-settings-button .drawer-icon::after { content: "⋆"; }
#persona-management-button .drawer-icon::after { content: "☼"; }
#rightNavHolder .drawer-icon::after { content: "◉"; }

#top-settings-holder > :is(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > .drawer-toggle:is(:hover, :focus-visible),
#top-settings-holder > :is(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > .drawer-toggle:has(.drawer-icon.openIcon) {
    color: var(--universe-light);
    border-bottom-color: var(--universe-light);
    background: linear-gradient(180deg, transparent 58%, rgba(191, 195, 204, .1));
    box-shadow: none;
    text-shadow: none !important;
    filter: none !important;
    transform: translateY(-1px);
}

#top-settings-holder > .drawer > .drawer-toggle:is(:hover, :focus-visible) > .drawer-icon,
#top-settings-holder > .drawer > .drawer-toggle > .drawer-icon.openIcon {
    color: var(--universe-light);
    opacity: 1;
    text-shadow: none !important;
    filter: none !important;
    transform: scale(1.04);
}

#top-settings-holder #API-status-top.redOverlayGlow {
    color: #c59191 !important;
    opacity: .92 !important;
    text-shadow: none !important;
    filter: none !important;
}

#top-settings-holder #API-status-top.greenOverlayGlow {
    color: #c7d4c3 !important;
    opacity: .96 !important;
    text-shadow: none !important;
    filter: none !important;
}

#top-settings-holder > .drawer > .drawer-toggle:active {
    transform: translateY(0) scale(.96);
}

/* SOURCE: src/windows/input.css */
/* ================================================================
   W03 输入区：星图工具带，原生菜单/魔法棒/发送/停止功能保留
   ================================================================ */
#send_form {
    color: var(--universe-light);
    border: 1px solid rgba(191, 195, 204, .48);
    border-radius: 0;
    background:
        radial-gradient(circle at 8% 24%, rgba(233, 236, 242, .18) 0 1px, transparent 1.8px),
        radial-gradient(circle at 38% 72%, rgba(191, 195, 204, .14) 0 1px, transparent 1.8px),
        radial-gradient(circle at 86% 28%, rgba(146, 149, 159, .15) 0 1px, transparent 1.8px),
        linear-gradient(90deg, rgba(16, 16, 19, .99), rgba(27, 28, 33, .95), rgba(16, 16, 19, .99));
    box-shadow: inset 0 1px 0 rgba(233, 236, 242, .05);
    text-shadow: none !important;
}

#send_textarea {
    margin: 0;
    padding: 11px 13px;
    color: var(--universe-light);
    border: 0;
    border-inline: 1px solid rgba(82, 85, 92, .72);
    border-radius: 0;
    background-color: rgba(16, 16, 19, .74);
    box-shadow: none;
    font-family: var(--universe-font-body);
    line-height: 1.62;
    text-shadow: none !important;
}

#send_textarea::placeholder { color: var(--universe-rule); }

#send_form:focus-within {
    border-color: var(--universe-light);
    box-shadow: inset 0 1px 0 rgba(233, 236, 242, .12);
}

#leftSendForm > div,
#rightSendForm > div,
#options_button,
#extensionsMenuButton,
#send_but,
#send_form .mes_stop {
    position: relative;
    color: var(--universe-silver);
    border: 0;
    border-bottom: 1px solid transparent;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
    text-shadow: none !important;
    filter: none !important;
}

#options_button::after,
#extensionsMenuButton::after,
#send_but::after,
#send_form .mes_stop::after {
    position: absolute;
    right: .02em;
    bottom: .02em;
    color: var(--universe-light);
    font: 400 .42em/1 var(--universe-font-label);
    opacity: .9;
    pointer-events: none;
    text-shadow: none !important;
}

#options_button::after { content: "◉"; }
#extensionsMenuButton::after { content: "✦"; }
#send_but::after { content: "☄"; }
#send_form .mes_stop::after { content: "◑"; }

#leftSendForm > div:is(:hover, :focus-visible),
#rightSendForm > div:is(:hover, :focus-visible),
#options_button:is(:hover, :focus-visible),
#extensionsMenuButton:is(:hover, :focus-visible),
#send_but:is(:hover, :focus-visible),
#send_form .mes_stop:is(:hover, :focus-visible) {
    color: var(--universe-light);
    border-bottom-color: var(--universe-light);
    background: linear-gradient(180deg, transparent 58%, rgba(191, 195, 204, .1));
    box-shadow: none;
    text-shadow: none !important;
    filter: none !important;
}

#send_but:is(:disabled, .disabled),
#send_form :is(.mes_stop, #options_button, #extensionsMenuButton).disabled {
    color: var(--universe-rule);
    opacity: .66;
    text-shadow: none !important;
}

#options,
#extensionsMenu {
    color: var(--universe-light);
    border: 1px solid var(--universe-rule-mid);
    border-radius: 0;
    background-image: var(--universe-panel-map);
    background-position: 0 0, 0 0, 0 0, center, right bottom;
    background-repeat: repeat, repeat, repeat, no-repeat, no-repeat;
    background-size: 220px 160px, 280px 190px, 320px 220px, 100% 100%, cover;
    box-shadow: var(--universe-shadow);
    text-shadow: none;
}

/* SOURCE: src/windows/common.css */
/* =========================================================
   W04 通用抽屉、表单与原生控件
   ========================================================= */
:is(.drawer-content, .wide100p):not(#chat) {
    color: var(--universe-text);
}

.drawer-content {
    background-color: var(--universe-panel-solid);
    background-image: var(--universe-panel-map);
    background-repeat: repeat, repeat, repeat, no-repeat, no-repeat;
    background-size: 220px 160px, 280px 190px, 340px 230px, 100% 100%, cover;
    border: 1px solid var(--universe-border);
    border-radius: var(--universe-radius-lg);
    box-shadow: var(--universe-shadow);
}

:is(.drawer-content, .popup, #options, #extensionsMenu) :is(input:not([type="range"]), textarea, select) {
    color: var(--universe-text);
    background: var(--universe-field);
    border: 1px solid var(--universe-border-soft);
    border-radius: var(--universe-radius-sm);
    box-shadow: none;
