    border-left: 3px solid var(--universe-silver);
    border-radius: var(--universe-radius-sm);
    box-shadow: var(--universe-shadow);
}

body #toast-container > .toast-success {
    border-left-color: #c7d4c3;
}

body #toast-container > .toast-info {
    border-left-color: #bfcfe2;
}

body #toast-container > .toast-warning {
    border-left-color: #d6c7a4;
}

body #toast-container > .toast-error {
    border-left-color: #d9aaaa;
}

body #toast-container > .toast :is(.toast-title, .toast-message) {
    color: inherit;
    text-shadow: none;
}

body #toast-container > .toast .toast-close-button {
    color: var(--universe-white);
    opacity: .82;
}

.swal2-popup,
.swal2-container .swal2-popup {
    color: var(--universe-text);
    background-color: var(--universe-panel-solid);
    background-image: var(--universe-panel-map);
    background-position: 0 0, 0 0, 0 0, center, right bottom;
    background-repeat: repeat, repeat, repeat, no-repeat, no-repeat;
    background-size: 210px 150px, 280px 190px, 340px 240px, 100% 100%, cover;
    border: 1px solid var(--universe-border);
    border-radius: var(--universe-radius-lg);
}

/* SOURCE: src/windows/mobile.css */
/* =========================================================
   手机端适配：保留整页宇宙海报，不把长文压成中轴两侧窄栏
   ========================================================= */
@media (max-width: 700px) {
    body {
        background-image: var(--universe-main-image);
        background-position: 64% center;
        background-repeat: no-repeat;
        background-size: auto 100vh;
        background-attachment: fixed;
        background-blend-mode: normal;
    }

    #sheld {
        border-inline: 0;
        box-shadow: none;
    }

    #chat {
        width: 100%;
        padding: 0 .48rem 7.1rem;
        border-inline: 0;
        background-color: rgba(16, 16, 19, .35);
        background-image:
            linear-gradient(90deg, rgba(16, 16, 19, .94), rgba(16, 16, 19, .72) 58%, rgba(16, 16, 19, .34)),
            var(--universe-main-image);
        background-position: center, 64% center;
        background-repeat: no-repeat, no-repeat;
        background-size: 100% 100%, auto 100vh;
        background-attachment: scroll, fixed;
        background-blend-mode: normal, normal;
    }

    #chat .mes:not([is_system="true"]) {
        width: 100%;
        margin: 0 0 1.2rem;
        padding: 1rem .65rem 1.2rem;
        border: 0;
        border-top: 1px solid rgba(191, 195, 204, .32);
        border-bottom: 1px solid rgba(191, 195, 204, .32);
        border-radius: 0;
        background: linear-gradient(90deg, rgba(16, 16, 19, .86), rgba(16, 16, 19, .5) 78%, rgba(16, 16, 19, .18));
        box-shadow: none;
    }

    #chat .mes[is_user="true"] {
        width: calc(100% - 3.2rem);
        margin-inline: 0 auto;
        border-left: 1px solid rgba(233, 236, 242, .58);
    }

    #chat .mes[is_user="false"]:not([is_system="true"]) {
        width: 100%;
        margin-inline: 0;
        border: 1px solid rgba(191, 195, 204, .3);
        border-right-color: rgba(233, 236, 242, .62);
        background-color: rgba(16, 16, 19, .8);
        background-image:
            linear-gradient(90deg, rgba(16, 16, 19, .96), rgba(16, 16, 19, .76) 68%, rgba(16, 16, 19, .34)),
            var(--universe-left-spine);
        background-position: center, calc(100% - .65rem) top;
        background-repeat: no-repeat, repeat-y;
        background-size: 100% 100%, 9rem auto;
        background-blend-mode: normal, normal;
    }

    #chat .mes[is_user="false"] > .mesAvatarWrapper {
        margin-inline: .7rem 0;
    }

    #chat .mes[is_user="true"] > .mesAvatarWrapper {
        margin-inline: 0 .7rem;
    }

    #chat .mes[is_user="false"] .avatar,
    #chat .mes[is_user="true"] .avatar {
        width: 2.75rem;
        height: 2.75rem;
        min-width: 2.75rem;
    }

    #chat .ch_name {
        padding: .15rem 0 .55rem;
    }

    #chat .mes[is_user="false"]:not([is_system="true"]) > .mes_block {
        padding-inline-end: 4.9rem;
    }

    #chat .mes[is_user="false"]:not([is_system="true"]) .ch_name {
        margin-bottom: .7rem;
        padding-block: .25rem .6rem;
    }

    #chat .name_text {
        font-size: 1.05rem;
    }

    #chat :is(.mes_text, .mes_reasoning),
    #chat .mes[is_user="true"] :is(.mes_text, .mes_reasoning),
    #chat .mes[is_user="false"] :is(.mes_text, .mes_reasoning) {
        padding: .72rem .42rem .9rem;
        border-inline: 0;
        font-size: .98rem;
        line-height: 1.88;
        letter-spacing: .018em;
    }

    #chat .mes[is_user="false"]:not([is_system="true"]) :is(.mes_text, .mes_reasoning) {
        padding-inline-end: .35rem;
    }

    #send_form {
        width: calc(100% - .8rem);
        bottom: .4rem;
        padding: .52rem;
        border-radius: 0;
        background: rgba(16, 16, 19, .94);
    }

    #top-bar,
    #top-settings-holder {
        padding-inline: .35rem;
    }

    #top-settings-holder .drawer-icon {
        min-width: 2rem;
        padding-inline: .25rem;
    }

    #rm_ch_create_block {
        background-position: 68% top;
        background-size: auto 100vh;
        background-attachment: fixed;
    }

    :is(#left-nav-panel, #right-nav-panel, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #rm_api_block, #AdvancedFormatting, #completion_prompt_manager) {
        border-radius: 0;
        box-shadow: none;
    }

    .popup,
    .modal-content,
    .dialogue_popup {
        max-width: calc(100% - 1rem);
        border-radius: var(--universe-radius-sm);
    }

    body #toast-container {
        width: calc(100% - 1rem);
        inset-inline: .5rem;
    }
}

